/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): curly_monsters - "processing實例｜我不想保持正確"
 * 原始作品討論 (Original Note): http://xhslink.com/o/1sy5Mg58nHd
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。幾何演算法靈感取材自 Michel Serres 時間混沌論
 * 及 curly_monsters 創作之「數字粒子與時間折疊排斥力場」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_PARTICLES = 12000;
let particles = [];
let clockDialX, clockDialY;
let dialAngle = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  background(220, 30, 8);

  clockDialX = width * 0.5;
  clockDialY = height * 0.5;

  // 初始化粒子群
  for (let i = 0; i < NUM_PARTICLES; i++) {
    particles.push({
      x: random(width),
      y: random(height),
      vx: 0,
      vy: 0,
      size: random(1.2, 2.5),
      life: random(1.0)
    });
  }
};

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.8 : 0.2));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.15;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.3;
  smoothedMid += (rawMid - smoothedMid) * 0.2;

  // 2. 尾蹟半透明沖刷（營造褶皺時間流痕）
  background(220, 25, 8, 0.15);

  // 3. 時鐘輪盤與奇點位置推進
  dialAngle += 0.02 + smoothedMid * 0.05;
  let targetDialX = width * 0.5 + sin(dialAngle * 0.8) * width * 0.2;
  let targetDialY = height * 0.5 + cos(dialAngle * 0.6) * height * 0.2;
  clockDialX += (targetDialX - clockDialX) * 0.05;
  clockDialY += (targetDialY - clockDialY) * 0.05;

  let repulseRadius = 180 + smoothedSubBass * 320;
  let repulseForce = 12.0 + smoothedSubBass * 28.0 + smoothedPercussive * 45.0;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 195;

  // 4. 繪製時鐘奇點輪盤 (Clock Dial Attractor)
  push();
  translate(clockDialX, clockDialY);
  rotate(dialAngle);
  noFill();
  stroke(currentHue, 70, 95, 0.4 + smoothedSubBass * 0.4);
  strokeWeight(1.5 + smoothedSubBass * 3);
  ellipse(0, 0, repulseRadius * 0.8, repulseRadius * 0.8);

  // 輪盤刻度
  for (let a = 0; a < TWO_PI; a += (Math.max(0.001, Math.abs(PI / 6)) || 1)) {
    let r1 = repulseRadius * 0.35;
    let r2 = repulseRadius * 0.4;
    line(cos(a) * r1, sin(a) * r1, cos(a) * r2, sin(a) * r2);
  }
  pop();

  // 5. 粒子排斥力場與軌跡更新
  noStroke();

  for (let i = 0; i < particles.length; i++) {
    let p = particles[i];

    // (a) 3D Perlin 雜訊流體向量
    let nAngle = noise(p.x * 0.002, p.y * 0.002, dialAngle * 0.5) * TWO_PI * 3.0;
    p.vx += cos(nAngle) * (0.3 + smoothedMid * 0.7);
    p.vy += sin(nAngle) * (0.3 + smoothedMid * 0.7);

    // (b) 排斥奇點「時間折疊力」
    let dx = p.x - clockDialX;
    let dy = p.y - clockDialY;
    let distSq = dx * dx + dy * dy;
    let dist = sqrt(distSq);

    if (dist < repulseRadius && dist > 1.0) {
      let force = (1.0 - dist / repulseRadius) * repulseForce;
      p.vx += (dx / dist) * force;
      p.vy += (dy / dist) * force;
    }

    // 重拍脈衝散裂
    if (smoothedPercussive > 0.6 && random() < 0.05) {
      let pAngle = random(TWO_PI);
      p.vx += cos(pAngle) * smoothedPercussive * 15.0;
      p.vy += sin(pAngle) * smoothedPercussive * 15.0;
    }

    // 速度衰減阻尼
    p.vx *= 0.92;
    p.vy *= 0.92;

    p.x += p.vx;
    p.y += p.vy;

    // 邊界邊緣循環重置
    if (p.x < 0) p.x = width;
    if (p.x > width) p.x = 0;
    if (p.y < 0) p.y = height;
    if (p.y > height) p.y = 0;

    // 繪製粒子 (動態色彩對應)
    let speed = sqrt(p.vx * p.vx + p.vy * p.vy);
    let particleHue = (currentHue + speed * 8.0) % 360;
    let particleSat = map(speed, 0, 20, 40, 95);
    let particleBri = map(speed, 0, 20, 70, 100);

    fill(particleHue, particleSat, particleBri, 0.75);
    ellipse(p.x, p.y, p.size * (1.0 + speed * 0.15), p.size * (1.0 + speed * 0.15));
  }
};

// === 運行時防崩潰護欄與 DOM 代理 Stubs ===
